@ zx_guest_image.S -- the ThreadX guest image, embedded in the hypervisor.
@
@ WHY A BLOB AND NOT A LINKED-IN LIBRARY
@
@   Because a guest ELF must never enter the hypervisor's link.  Two
@   ThreadX-shaped images in one link resolve into each other silently:
@   objects beat static libraries at link time, so the guest's copy of a
@   symbol and the hypervisor's are chosen by link order rather than by
@   intent, and the resulting image builds and reports a plausible size.
@
@   So the guest is built as a separate program, by a separate toolchain
@   invocation, reduced to a raw binary with objcopy, and pulled in HERE as
@   opaque bytes.  The hypervisor's linker sees a lump of data with two
@   symbols around it and no symbols inside it, which is exactly the right
@   amount of coupling.
@
@ .incbin SEARCHES THE ASSEMBLER'S INCLUDE PATH, NOT THE COMPILER'S
@
@   -I on the compiler command line does not reach the assembler; it needs
@   -Wa,-I.  The example's CMakeLists passes the guest's build directory that
@   way through set_source_files_properties on this file.  Getting it wrong
@   fails the assembly with "file not found", which is the good outcome and
@   the reason this is written down: the neighbouring mistake -- a LINKER
@   input pattern that matches nothing -- does not fail at all.  It produces
@   an empty section at whatever address the location counter held, and an
@   image that builds, links, reports a plausible size and contains no guest.
@
@   Two independent checks exist for that, because it has happened before:
@   the linker script asserts the blob is bigger than the header it must
@   contain, and the loader checks the image's own magic number before it
@   ERETs anywhere.

#include "zx_guest_abi.h"

    .section .zx_guest_a_blob, "a", %progbits
    .balign 64

    .global __zx_guest_a_image_start
__zx_guest_a_image_start:

    .incbin "guest_a.bin"

    .balign 4
    .global __zx_guest_a_image_end
__zx_guest_a_image_end:
